<?php
$page_title='คำขอผู้ขาย';require_once __DIR__.'/../includes/auth_check.php';requireAdmin();require_once __DIR__.'/../config/database.php';$db=(new Database())->getConnection();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);$userId=(int)($_POST['user_id']??0);$action=$_POST['action']??'';$note=trim((string)($_POST['admin_note']??''));if(!$db||!$userId||!in_array($action,['approve','reject'],true))$error='ข้อมูลคำขอไม่ถูกต้อง';else{try{$db->beginTransaction();$status=$action==='approve'?'approved':'rejected';$update=$db->prepare('UPDATE seller_profiles SET status=?,admin_note=?,reviewed_at=NOW(),reviewed_by=? WHERE user_id=? AND status="pending"');$update->execute([$status,$note,(int)$_SESSION['user_id'],$userId]);if($update->rowCount()!==1)throw new RuntimeException('คำขอนี้ถูกดำเนินการแล้ว');if($action==='approve'){$role=$db->prepare("UPDATE users SET role='seller' WHERE id=? AND role='customer'");$role->execute([$userId]);}createNotification($db,$userId,'seller',$action==='approve'?'ร้านค้าของคุณได้รับอนุมัติแล้ว':'คำขอเปิดร้านยังไม่ผ่านการอนุมัติ',$note?:($action==='approve'?'คุณสามารถเริ่มเพิ่มสินค้าได้แล้ว':'กรุณาตรวจสอบหมายเหตุจากทีมงาน'),BASE_URL.($action==='approve'?'seller-dashboard.php':'seller.php'));$db->commit();$message=$action==='approve'?'อนุมัติผู้ขายเรียบร้อย':'ปฏิเสธคำขอเรียบร้อย';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}}
$profiles=$db?$db->query('SELECT sp.*,u.username,u.email,u.full_name,c.name category_name FROM seller_profiles sp JOIN users u ON u.id=sp.user_id JOIN categories c ON c.id=sp.primary_category_id ORDER BY FIELD(sp.status,"pending","approved","rejected"),sp.submitted_at ASC')->fetchAll():[];require_once __DIR__.'/../includes/admin_header.php';
?><header class="admin-page-header"><div><p class="eyebrow">SELLER ONBOARDING</p><h1>คำขอผู้ขาย</h1><p>ตรวจสอบข้อมูลรับเงินและอนุมัติร้านก่อนเปิดสิทธิ์ขาย</p></div></header><?php if($message): ?><div class="admin-alert success"><?php echo e($message); ?></div><?php endif;if($error): ?><div class="admin-alert error"><?php echo e($error); ?></div><?php endif; ?><section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ร้าน / เจ้าของ</th><th>หมวด</th><th>รับเงิน</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody><?php if(!$profiles): ?><tr><td class="admin-empty" colspan="5">ยังไม่มีคำขอผู้ขาย</td></tr><?php endif;foreach($profiles as $profile): ?><tr><td><span class="cell-title"><?php echo e($profile['shop_name']); ?></span><span class="cell-subtitle"><?php echo e($profile['full_name']); ?> · <?php echo e($profile['email']); ?></span><span class="cell-subtitle"><?php echo e($profile['phone']); ?></span></td><td><?php echo e($profile['category_name']); ?></td><td><span class="cell-title"><?php echo $profile['payout_method']==='promptpay'?'PromptPay':'บัญชีธนาคาร'; ?></span><span class="cell-subtitle"><?php echo e($profile['payout_account_name']); ?> · <?php echo e($profile['payout_account_number']); ?></span></td><td><span class="status-badge <?php echo $profile['status']==='approved'?'paid':($profile['status']==='rejected'?'cancelled':'pending'); ?>"><?php echo e($profile['status']); ?></span></td><td><?php if($profile['status']==='pending'): ?><form method="POST" class="table-actions"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken()); ?>"><input type="hidden" name="user_id" value="<?php echo (int)$profile['user_id']; ?>"><input name="admin_note" maxlength="500" placeholder="หมายเหตุ"><button class="btn btn-primary" name="action" value="approve">อนุมัติ</button><button class="btn btn-danger" name="action" value="reject">ปฏิเสธ</button></form><?php else: ?><small><?php echo e($profile['admin_note']?:'-'); ?></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php require_once __DIR__.'/../includes/admin_footer.php'; ?>
